package com.library.management.util;

/*
 * LoggingNotificationObserver.java
 * Purpose: Logs user-facing notifications generated by the reservation flow.
 * What this file contains:
 * - a simple observer that writes reservation notifications through java.util.logging
 * Why it exists:
 * - turns the notification extension point into a real reservation feature
 */

import java.util.logging.Logger;

public class LoggingNotificationObserver implements LibraryNotificationObserver {
    private static final Logger LOGGER = Logger.getLogger(LoggingNotificationObserver.class.getName());

    @Override
    public void onNotify(String eventType, String message) {
        LOGGER.info("Notification [" + eventType + "]: " + message);
    }
}
